/**
 * Agent Host — utilityProcess entry.
 * Runs pi-coding-agent in-process; serves Api/Streams over MessagePort.
 */
import { createRpcServer } from "../contract/rpc";
import { registerHandlers } from "./handlers";
import { startSessionWatcher } from "./session-watcher";
import { toolchainRuntime } from "./toolchain-runtime";
import type { ToolchainSnapshot } from "../shared/toolchains/types";
import { installToolchainGitRunner } from "./toolchain-git";
import type { BrowserCapabilitySnapshot } from "../contract/browser";
import { browserCapabilityRuntime } from "./browser-capability-runtime";
import { syncBrowserToolsForAllSessions } from "./rpc-manager";
import { readPiRuntimeVersion } from "./runtime-version";
import { applyManagedProcessOwnerIdentity } from "./managed-process/owner-identity";

const piRuntimeVersion = readPiRuntimeVersion();

const server = createRpcServer();
const restoreGitRunner = installToolchainGitRunner();
const stopHandlers = registerHandlers(server);
const stopWatcher = startSessionWatcher(server);

function log(message: string): void {
  try {
    process.parentPort?.postMessage({ type: "log", message });
  } catch {
    console.log(`[agent-host] ${message}`);
  }
}

// Electron utilityProcess parent messaging
const parentPort = process.parentPort;
if (parentPort) {
  parentPort.on("message", (event) => {
    const msg = event.data as {
      type?: string;
      snapshot?: ToolchainSnapshot | BrowserCapabilitySnapshot;
      version?: unknown;
      mainPid?: unknown;
      mainStartFingerprint?: unknown;
      mainImagePath?: unknown;
      hostInstanceId?: unknown;
    };
    if (msg?.type === "ping") {
      parentPort.postMessage({ type: "pong", ts: Date.now() });
      return;
    }
    if (msg?.type === "attach-port") {
      const port = event.ports?.[0];
      if (port) {
        try {
          server.attachPort(port as never);
          log("renderer port attached");
        } catch (err) {
          log(`attach-port failed: ${err instanceof Error ? err.message : String(err)}`);
        }
      } else {
        log("attach-port: no port in event");
      }
      return;
    }
    if (msg?.type === "managed-process-owner:init") {
      try {
        const owner = applyManagedProcessOwnerIdentity(msg);
        parentPort.postMessage({
          type: "managed-process-owner:ack",
          version: 1,
          hostInstanceId: owner.hostInstanceId,
        });
      } catch (error) {
        log(`managed process owner identity rejected: ${error instanceof Error ? error.message : String(error)}`);
      }
      return;
    }
    if (msg?.type === "toolchain:init" || msg?.type === "toolchain:changed") {
      try {
        if (!msg.snapshot) throw new Error("missing snapshot");
        toolchainRuntime.apply(msg.snapshot as ToolchainSnapshot);
        parentPort.postMessage({ type: "toolchain:ack", revision: msg.snapshot.revision });
        log(`toolchain ${msg.type === "toolchain:init" ? "initialized" : "updated"} revision=${msg.snapshot.revision}`);
      } catch (error) {
        log(`toolchain snapshot rejected: ${error instanceof Error ? error.message : String(error)}`);
      }
      return;
    }
    if (msg?.type === "browser:init" || msg?.type === "browser:changed") {
      try {
        if (!msg.snapshot) throw new Error("missing snapshot");
        browserCapabilityRuntime.apply(msg.snapshot as BrowserCapabilitySnapshot);
        syncBrowserToolsForAllSessions();
        parentPort.postMessage({ type: "browser:ack", revision: msg.snapshot.revision });
        log(`browser ${msg.type === "browser:init" ? "initialized" : "updated"} revision=${msg.snapshot.revision}`);
      } catch (error) {
        log(`browser capability snapshot rejected: ${error instanceof Error ? error.message : String(error)}`);
      }
      return;
    }
    if (msg?.type === "shutdown") {
      stopWatcher();
      restoreGitRunner();
      void stopHandlers().finally(() => process.exit(0));
    }
  });

  parentPort.postMessage({ type: "ready", ts: Date.now(), piVersion: piRuntimeVersion });
  log("agent-host ready");
} else {
  // Fallback for non-electron (smoke / unit)
  console.log("[agent-host] no parentPort — standalone mode");
}

process.on("uncaughtException", (err) => {
  log(`uncaughtException: ${err instanceof Error ? (err.stack ?? err.message) : String(err)}`);
  // Do not keep serving requests from a potentially corrupted Host. The main
  // process supervisor will restart this utility process within its budget.
  setImmediate(() => process.exit(1));
});
process.on("unhandledRejection", (err) => {
  log(`unhandledRejection: ${err instanceof Error ? (err.stack ?? err.message) : String(err)}`);
  setImmediate(() => process.exit(1));
});

// Keep alive
setInterval(() => {}, 1 << 30);

import type {
  AgentCommand,
  AgentEvent,
  CredentialMutationResult,
  DirEntry,
  EntryContentResult,
  FileContent,
  FileMeta,
  HistoryWindow,
  LoginProgressEvent,
  ModelPreferencesResult,
  ModelsConfig,
  ModelsConfigSnapshot,
  ModelsListResult,
  PagedContextInfo,
  ProviderStatus,
  RunningStateEvent,
  SessionDetail,
  SessionInfo,
  TestResult,
  WorktreeInfo,
} from "./types";
import type {
  GitStatusResult,
  PluginActionParams,
  PluginsResponse,
  SkillRecord,
  SkillUpdateParams,
} from "../shared/api-types";
import type {
  ChannelAccountConfig,
  ChannelBinding,
  ChannelBindingChange,
  ChannelLoginEvent,
  ChannelLoginStartRequest,
  ChannelProbeResult,
  ChannelsSnapshot,
  ChannelStatus,
  ChannelPairingRequest,
  ChannelActivity,
  ChannelId,
  ChannelTestSendResult,
} from "../shared/channel-types";
import type { ToolCapabilityId, ToolProvider } from "../shared/toolchains/types";
import type {
  ManagedProcessChangedEvent,
  ManagedProcessLogStream,
  ManagedProcessLogWindow,
  ManagedProcessOutputEvent,
  ManagedProcessPublicInfo,
  ManagedProcessReadParams,
  ManagedProcessWaitParams,
  ManagedProcessWriteParams,
} from "./processes";

/** Request/response API surface (replaces HTTP routes). */
export interface Api {
  "host.ping": { params: void; result: { ok: true; ts: number } };
  "host.toolchain": {
    params: { cwd: string };
    result: {
      inventoryRevision: number;
      resolutionId: string;
      capabilities: Partial<Record<ToolCapabilityId, { provider: ToolProvider; version: string }>>;
    };
  };

  // Managed background processes (trusted Renderer control surface)
  "processes.list": {
    params: { includeExited?: boolean } | void;
    result: { revision: number; processes: ManagedProcessPublicInfo[] };
  };
  "processes.get": {
    params: { processId: string };
    result: ManagedProcessPublicInfo;
  };
  "processes.read": {
    params: ManagedProcessReadParams;
    result: ManagedProcessLogWindow;
  };
  "processes.wait": {
    params: ManagedProcessWaitParams;
    result: ManagedProcessLogWindow;
  };
  "processes.write": {
    params: ManagedProcessWriteParams;
    result: { ok: true; runId: string };
  };
  "processes.stop": {
    params: { processId: string; runId: string; mode?: "graceful" | "force" };
    result: ManagedProcessPublicInfo;
  };
  "processes.stopAll": {
    params: { mode?: "graceful" | "force" } | void;
    result: { ok: true; stopped: number };
  };
  "processes.restart": {
    params: { processId: string; runId: string };
    result: ManagedProcessPublicInfo;
  };
  "processes.dismiss": {
    params: { processId: string };
    result: { ok: true };
  };
  "processes.export": {
    params: { processId: string; runId: string; streams?: ManagedProcessLogStream[] };
    result: { saved: boolean; fileName?: string };
  };

  // Sessions & projects
  "sessions.list": {
    params: { cwd?: string } | void;
    result: { sessions: SessionInfo[]; runningSessionIds: string[] };
  };
  "sessions.get": {
    params: { id: string; includeState?: boolean; traceId?: string; historyWindow?: HistoryWindow };
    result: SessionDetail;
  };
  "sessions.context": {
    params: { id: string; leafId?: string; historyWindow?: HistoryWindow };
    result: { context: PagedContextInfo };
  };
  "sessions.contextPage": {
    params: { id: string; cursor: string; maxTurns?: number; maxBytes?: number };
    result: { context: PagedContextInfo };
  };
  "sessions.entryContent": {
    params: { id: string; entryId: string; blockIndex?: number };
    result: EntryContentResult;
  };
  "sessions.export": {
    params: { id: string; format?: "md" | "json" };
    result: { content: string; suggestedName: string };
  };
  "sessions.delete": { params: { id: string; force?: boolean }; result: { ok: true } };
  "sessions.rename": {
    params: { id: string; name: string };
    result: { ok: true };
  };

  "worktrees.list": {
    params: { projectRoot: string };
    result: {
      worktrees: WorktreeInfo[];
      projectRoot: string;
      isGit: boolean;
      isTopLevel: boolean;
    };
  };
  "worktrees.create": {
    params: { projectRoot: string; branch: string; cwd?: string };
    result: { worktree: WorktreeInfo };
  };
  "worktrees.remove": {
    params: { path: string; cwd?: string; force?: boolean };
    result: { ok: true };
  };

  "git.status": {
    params: { path: string };
    result: GitStatusResult;
  };

  // Agent lifecycle
  "agent.new": {
    params: {
      cwd: string;
      type?: string;
      message?: string;
      provider?: string;
      modelId?: string;
      toolNames?: string[];
      thinkingLevel?: string;
      [key: string]: unknown;
    };
    result: { sessionId: string; data?: unknown };
  };
  "agent.command": {
    params: { sessionId: string; command: AgentCommand };
    result: unknown;
  };
  "agent.state": {
    params: { sessionId: string };
    result: { running: boolean; state?: unknown };
  };
  /** Generate a concise session title from the first user message (silent LLM request, never touches session history). */
  "agent.generateTitle": {
    params: {
      sessionId: string;
      message: string;
      provider?: string;
      modelId?: string;
    };
    result: { title: string | null };
  };

  // Messaging channels
  "channels.list": { params: void; result: ChannelsSnapshot };
  "channels.accountUpsert": {
    params: { account: ChannelAccountConfig };
    result: ChannelsSnapshot;
  };
  "channels.accountConnect": {
    params: { account: ChannelAccountConfig };
    result: ChannelsSnapshot;
  };
  "channels.accountDelete": {
    params: { accountId: string };
    result: ChannelsSnapshot;
  };
  "channels.start": { params: { accountId: string }; result: { ok: true } };
  "channels.stop": { params: { accountId: string }; result: { ok: true } };
  "channels.restart": { params: { accountId: string }; result: { ok: true } };
  "channels.probe": { params: { accountId: string }; result: ChannelProbeResult };
  "channels.loginStart": {
    params: ChannelLoginStartRequest;
    result: ChannelLoginEvent;
  };
  "channels.loginWait": {
    params: { channel: ChannelId; sessionKey: string };
    result: ChannelLoginEvent;
  };
  "channels.loginSubmitCode": {
    params: { channel: ChannelId; sessionKey: string; code: string };
    result: { ok: true };
  };
  "channels.loginCancel": {
    params: { channel: ChannelId; sessionKey: string };
    result: { ok: true };
  };
  "channels.pairingApprove": {
    params: { pairingId: string };
    result: ChannelsSnapshot;
  };
  "channels.pairingReject": {
    params: { pairingId: string };
    result: ChannelsSnapshot;
  };
  "channels.bindingUpsert": {
    params: { binding: ChannelBinding };
    result: ChannelsSnapshot;
  };
  "channels.bindingDelete": {
    params: { bindingId: string };
    result: ChannelsSnapshot;
  };
  "channels.testSend": {
    params: { accountId: string; peerId: string; message: string };
    result: ChannelTestSendResult;
  };

  // Files
  "files.list": { params: { path: string }; result: { entries: DirEntry[] } };
  "files.read": {
    params: { path: string; sourceSessionId?: string };
    result: FileContent & {
      encoding?: "utf8" | "base64" | "too_large";
      mime?: string;
    };
  };
  "files.download": {
    params: { path: string; sourceSessionId?: string };
    result: { base64: string; size: number; mime: string };
  };
  "files.meta": {
    params: { path: string; sourceSessionId?: string };
    result: FileMeta;
  };
  "files.preview": {
    params: { path: string; sourceSessionId?: string };
    result: { kind: string; content?: string; base64?: string; mime?: string; [key: string]: unknown };
  };
  "files.index": {
    params: { root: string; query?: string };
    result: {
      files: string[];
      truncated: boolean;
      truncatedReason?: "depth" | "count";
      matches?: Array<{ path: string; isDir?: boolean; score?: number }>;
      degradedReason?: "search-unavailable" | "search-timeout" | "search-failed";
    };
  };
  "files.watchStart": {
    params: { path: string; sourceSessionId?: string };
    result: { ok: true };
  };
  "files.watchStop": {
    params: { path: string };
    result: { ok: true };
  };

  // Config
  "models.list": {
    params: { cwd?: string } | void;
    result: ModelsListResult;
  };
  "models.refresh": {
    params: { cwd?: string; requestId: string };
    result: ModelsListResult;
  };
  "models.refreshCancel": {
    params: { requestId: string };
    result: { ok: true; cancelled: boolean };
  };
  "models.preferences.get": {
    params: { cwd?: string } | void;
    result: ModelPreferencesResult;
  };
  "models.preferences.set": {
    params: { cwd?: string; enabledModels: string[] | null };
    result: ModelPreferencesResult;
  };
  "modelsConfig.get": { params: void; result: ModelsConfigSnapshot };
  "modelsConfig.set": {
    params: { config: ModelsConfig; expectedVersion: string };
    result: { ok: true; version: string };
  };
  "modelsConfig.test": {
    params: {
      providerName?: string;
      provider?: Record<string, unknown>;
      model?: Record<string, unknown>;
      [key: string]: unknown;
    };
    result: TestResult;
  };

  "auth.providers": { params: void; result: { providers: ProviderStatus[] } };
  "auth.allProviders": { params: void; result: { providers: ProviderStatus[] } };
  "auth.setApiKey": {
    params: { provider: string; key: string };
    result: CredentialMutationResult;
  };
  "auth.deleteApiKey": {
    params: { provider: string };
    result: CredentialMutationResult;
  };
  "auth.logout": { params: { provider: string }; result: CredentialMutationResult };
  "auth.loginSubmit": {
    params: { provider: string; token: string; code: string };
    result: { ok: true };
  };
  /** Kick off OAuth login; progress arrives on Streams["auth.login"]. */
  "auth.loginStart": {
    params: { provider: string };
    result: { ok: true; started: boolean };
  };
  "auth.loginCancel": {
    params: { provider: string };
    result: { ok: true };
  };

  "skills.list": {
    params: { cwd?: string } | void;
    result: { skills: SkillRecord[]; diagnostics?: unknown[] };
  };
  "skills.search": {
    params: { query: string };
    result: { results: unknown[] };
  };
  "skills.install": {
    params: { package: string; [key: string]: unknown };
    result: { ok: true; [key: string]: unknown };
  };
  "skills.set": {
    params: SkillUpdateParams;
    result: { ok: true };
  };
  "skills.getContent": {
    params: { cwd: string; filePath: string };
    result: { content: string };
  };

  "plugins.list": {
    params: { cwd?: string } | void;
    result: PluginsResponse;
  };
  "plugins.set": {
