  earliestCursor: string;
  latestCursor: string;
  retainedBytes: number;
  droppedBytes: number;
  droppedRecords: number;
}

export interface ManagedProcessPublicInfo {
  processId: string;
  runId: string;
  generation: number;
  label: string;
  kind: ManagedProcessKind;
