    const encrypted = this.codec.encrypt(value).toString("base64");
    this.secrets.set(ref, encrypted);
    this.persist();
    return ref;
  }

  get(ref: string): string | undefined {
    const encrypted = this.secrets.get(validateSecretRef(ref));

