  | { type: "error"; message: string }
  | { type: "cancelled" };

export interface RpcErrorShape {
  code: string;
  message: string;
  detail?: unknown;
}

export class RpcError extends Error {
  code: string;
  detail?: unknown;

  constructor(shape: RpcErrorShape) {
    super(shape.message);
    this.name = "RpcError";
    this.code = shape.code;
    this.detail = shape.detail;
  }
}

