      "$1=[REDACTED]",
    )
    .replace(/([?&](?:access_token|auth|key|password|secret|token)=)[^&#\s]+/gi, "$1[REDACTED]")
    .replace(/\b[A-Z]:\\Users\\[^\\\s"']+(?:\\[^\s"']*)?/gi, "[LOCAL_PATH]")
    .replace(/\/(?:Users|home)\/[^/\s"']+(?:\/[^\s"']*)?/g, "[LOCAL_PATH]")
